// Find the knowledge panel in the right sidebar
const kpSource = document.querySelector('#uLEOKb .pxiwBd');
if (!kpSource) return;

// Check if we already inserted the clone to avoid duplicates
if (element.querySelector('.cats-kp-injected')) return;

// Clone the entire knowledge panel
const clone = kpSource.cloneNode(true);
clone.classList.add('cats-kp-injected');

// Style the clone so it looks natural in the left column
clone.style.cssText = `
  display: block;
  width: 100%;
  max-width: 652px;
  margin: 0 0 24px 0;
  padding: 16px;
  background: #fff;
  border: 1px solid #dadce0;
  border-radius: 12px;
  box-shadow: 0 1px 6px rgba(32,33,36,.18);
  box-sizing: border-box;
`;

// Remove any width constraints inside the clone that assume sidebar width
const innerLayout = clone.querySelector('.e8Ck0d');
if (innerLayout) {
  innerLayout.style.cssText = 'width: 100% !important; max-width: 100% !important;';
}

// Hide the original in the sidebar so it doesn't duplicate
kpSource.style.display = 'none';

// Insert at the top of #topstuff
element.appendChild(clone);
